-- Fix one factual table error and restore operational details in level-5 Russian cards.
update public.spell_catalog
set notes = 'Официальная таблица SRD 5.2.1: 1 — Аасимар; 2 — Драконорождённый; 3 — Дварф; 4 — Эльф; 5 — Гном; 6 — Голиаф; 7 — Полурослик; 8 — Человек; 9 — Орк; 10 — Тифлинг. Мастер может выбрать другой игровой вид.'
where slug = 'reincarnate';

update public.spell_catalog
set effect_summary = 'Создаёшь Большую руку с КД 20 и HP, равными твоему максимуму HP. При наложении и затем бонусным действием можешь переместить её до 60 футов и выбрать эффект: Сжатый кулак — рукопашная атака на 5к8 силового; Толкающая рука — при провале спасброска Силы толкает Огромную или меньшую цель на 5 футов + 5 × модификатор твоей характеристики заклинаний и следует за ней; Хватающая рука — при провале спасброска Ловкости Захватывает Огромную или меньшую цель, после чего бонусным действием может сжимать её на 4к6 + модификатор характеристики заклинаний дробящего урона; Преграждающая рука даёт тебе Полуукрытие от атак и эффектов, исходящих из её пространства или проходящих через него, а её пространство является труднопроходимым для врагов.'
where slug = 'arcane-hand';

update public.spell_catalog
set notes = 'Враждебное связанное существо выполняет приказы, но старается толковать их в своих интересах. Обычно цель сначала удерживают инвертированным Магическим кругом. Если существо полностью выполнило приказ до окончания заклинания и вы на одном плане, оно приходит к тебе сообщить об этом; если вы на разных планах, оно возвращается к месту связывания и остаётся там до конца эффекта.'
where slug = 'planar-binding';

update public.spell_catalog
set notes = 'Каждая панель: КД 15, 30 HP за каждый дюйм толщины, иммунитет к яду и психическому урону. Если создаёшь пролёт длиной больше 20 футов, размер каждой панели нужно уменьшить вдвое, чтобы сделать опоры. Если удерживать концентрацию все 10 минут, стена становится постоянной и уже не может быть рассеяна; иначе исчезает с окончанием заклинания.'
where slug = 'wall-of-stone';

update public.spell_catalog
set notes = 'Модификатор спасброска по знакомству: слышал +5, встречал +0, хорошо знаешь −5. Связь: изображение −2, вещь цели −4, часть тела/волос/ноготь −10. При успешном спасброске цель не затронута, и повторно наблюдать её этим заклинанием нельзя 24 часа. Цель не знает причину броска. Существо, способное видеть невидимый сенсор, видит его как светящийся шар размером примерно с кулак.'
where slug = 'scrying';

update public.spell_catalog
set effect_summary = 'Навсегда наполняешь область святой или нечестивой силой. Выбираешь типы существ из Аберраций, Небожителей, Элементалей, Фей, Исчадий и Нежити: выбранные типы не могут добровольно войти, а Одержимость, Очарование и Испуг, вызванные ими, подавляются в области. Дополнительно выбираешь один эффект: Храбрость; Тьма; Дневной свет; Покой мёртвых; блок телепортации и межпланарных переходов; Страх; Сопротивление одному типу урона; Тишина; Языки; либо Уязвимость к одному типу урона.',
    notes = 'Если выбранный радиус пересекается с уже действующим Освящением, новое заклинание проваливается. Для Храбрости, Страха, Сопротивления, межпространственного запрета, Языков и Уязвимости при наложении выбираешь типы существ, на которые действует дополнительный эффект. Тьма не освещается обычным светом и магическим светом заклинаний ниже 5 уровня; Дневной свет не гасится магической Тьмой заклинаний ниже 5 уровня. Покой мёртвых запрещает превращать захороненные здесь тела в Нежить. Тишина полностью блокирует звук через границу области. Материал расходуется.'
where slug = 'hallow';

-- Normalize direct address in level-5 cards.
update public.spell_catalog
set notes = 'Пробуждённая цель Очарована тобой 30 дней или пока она не получит урон от тебя или твоих союзников. После окончания Очарования она сама определяет отношение к тебе.'
where slug = 'awaken';

update public.spell_catalog
set effect_summary = 'При провале гуманоид становится Очарованным. Пока ты и цель находитесь на одном плане, можешь телепатически отдавать ему команды без действия. Чтобы приказать цели использовать Реакцию, тратишь собственную Реакцию.',
    check_type = 'Спасбросок Мудрости; с преимуществом, если ты или твои союзники сражаетесь с целью; повтор после каждого получения урона'
where slug = 'dominate-person';

update public.spell_catalog
set check_type = 'Спасбросок Мудрости; с преимуществом, если ты сражаешься с целью'
where slug = 'modify-memory';
